insert into public.deals (external_key, date, date_text, kind, asset_class, sport, target, target_kind, target_country, target_team_id, target_company_id, investor, investor_type, investor_company_id, investor_id, seller, stake_pct, amount, currency, valuation, valuation_currency, headline, summary, source_name, source_url, source)
  values ('deal:brentford-football-club:matthew-benham:february-2025', null, 'February 2025', 'other', 'sports', 'football', 'Brentford Football Club', 'club', 'England', (select id from public.sports_teams where external_key = 'premier-league--brentford'), null, 'Matthew Benham', 'individual', (select id from public.companies where lower(name) = lower('Matthew Benham') limit 1), (select id from public.sports_investors where lower(name) = lower('Matthew Benham') limit 1), null, null, null, null, null, null, 'Benham moves Brentford shares into new holding company Best Intentions Analytics', 'Matthew Benham transferred his shares in Brentford into a newly formed holding company, Best Intentions Analytics Limited (BIA), a restructuring the club says enabled it to secure outside investment.', 'Brentford FC', 'https://www.brentfordfc.com/en/news/article/club-news-brentford-new-investment-gary-lubner-sir-matthew-vaughn', 'web_research')
